// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: oswaldFamily } = loadOswald();
const { fontFamily: interFamily } = loadInter();



export type CortisolSpikeProps = Record<string, any>;

const CortisolSpike: React.FC<CortisolSpikeProps> = ({
  backgroundColor = "#03030b",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryTitle = "CORTISOL",
  secondaryTitle = "SPIKE",
  primaryColor = "#FFFFFF",
  accentColor = "#FF3D3D",
  peakValue = 176,
  baselineValue = 98,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Animation timeline configuration
  const spikeStartFrame = 35;
  const spikeEndFrame = 115;

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Spring & Easing calculations
  const title1Spring = spring({
    frame: Math.max(0, frame - 5),
    fps,
    config: { damping: 14, mass: 0.6, stiffness: 90 },
  });

  const title2Spring = spring({
    frame: Math.max(0, frame - 15),
    fps,
    config: { damping: 14, mass: 0.6, stiffness: 90 },
  });

  const badgeSpring = spring({
    frame: Math.max(0, frame - spikeStartFrame),
    fps,
    config: { damping: 12, mass: 0.5, stiffness: 100 },
  });

  // Calculate percentage count-up in sync with chart spike
  const countProgress = interpolate(frame, [spikeStartFrame, spikeEndFrame], [baselineValue, peakValue], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 0.1, 0.25, 1),
  });

  // Responsive dial properties with increased radius for breathing room
  const dialRadius = Math.min(width, height) * 0.155;
  const dialCircumference = 2 * Math.PI * dialRadius;
  
  // Progress circular track scaling (capped to match the gap sweep)
  const maxDialRange = peakValue * 1.25; 
  const dialProgress = countProgress / maxDialRange;
  const strokeDashoffset = dialCircumference * (1 - dialProgress);

  // SVG dimensions for Dial centering
  const dialSvgSize = dialRadius * 2 + 40;
  const dialCenter = dialSvgSize / 2;

  // Generate smooth biological-like spiky path
  const points = React.useMemo(() => {
    const pts = [];
    const totalPoints = 160;
    for (let i = 0; i <= totalPoints; i++) {
      const x = 50 + (i / totalPoints) * 850; // maps from 50 to 900
      const t = i / totalPoints;
      
      let baseHeight = 265;
      if (t > 0.45) {
        // Dramatic curve rise mimicking standard cortisol release spikes
        const riseT = (t - 0.45) / 0.55;
        baseHeight = 265 - Math.pow(riseT, 3) * 205;
      }
      
      // Micro-fluctuations mimicking authentic biological signals
      const freq = t < 0.45 ? 16 : 28;
      const amp = t < 0.45 ? 2.5 : 4 * (1 - Math.pow(t - 0.8, 2));
      const noise = Math.sin(t * freq * Math.PI * 2) * amp;
      
      const y = baseHeight + noise;
      pts.push({ x, y });
    }
    return pts;
  }, []);

  // Compute currently revealed portion of the spiky path
  const visiblePointsCount = Math.floor(
    interpolate(frame, [spikeStartFrame, spikeEndFrame], [1, points.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );
  
  const slicedPoints = points.slice(0, visiblePointsCount);
  const hasPoints = slicedPoints.length >= 2;
  const linePath = hasPoints ? "M " + slicedPoints.map(p => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(" L ") : "";
  const fillPath = hasPoints ? `${linePath} L ${slicedPoints[slicedPoints.length - 1].x.toFixed(1)},270 L ${slicedPoints[0].x.toFixed(1)},270 Z` : "";
  const leadPoint = slicedPoints[slicedPoints.length - 1];

  // Micro animation metrics
  const text1Reveal = interpolate(title1Spring, [0, 1], [-40, 0]);
  const text2Reveal = interpolate(title2Spring, [0, 1], [40, 0]);
  const pulseScale = interpolate(Math.sin(frame * 0.15), [-1, 1], [1, 1.6]);
  const pulseOpacity = interpolate(Math.sin(frame * 0.15), [-1, 1], [0.7, 0.1]);
  const pulseBlink = frame > spikeEndFrame ? (Math.floor(frame / 6) % 2 === 0 ? 1 : 0.4) : 1;

  // Static vertical grid intervals
  const verticalGridLines = [220, 420, 620, 820];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        backgroundImage: `radial-gradient(circle at 75% 30%, ${accentColor}10 0%, transparent 60%)`,
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* LEFT COLUMN: TITLE & BADGE CONTAINER */}
      <div
        style={{
          position: "absolute",
          top: height * 0.22,
          left: width * 0.08,
          width: width * 0.45,
          display: "flex",
          flexDirection: "column",
          justifyContent: "flex-start",
          zIndex: 10,
          transition: "none",
        }}
      >
        <h1
          style={{
            fontFamily: oswaldFamily,
            fontSize: height * 0.13,
            fontWeight: 800,
            color: primaryColor,
            lineHeight: 0.9,
            letterSpacing: "0.02em",
            textTransform: "uppercase",
            margin: 0,
            padding: 0,
            opacity: title1Spring,
            transform: `translateX(${text1Reveal}px)`,
            transition: "none",
          }}
        >
          {primaryTitle}
        </h1>
        <h2
          style={{
            fontFamily: oswaldFamily,
            fontSize: height * 0.13,
            fontWeight: 800,
            color: accentColor,
            lineHeight: 0.9,
            letterSpacing: "0.02em",
            textTransform: "uppercase",
            margin: 0,
            padding: 0,
            opacity: title2Spring,
            transform: `translateX(${text2Reveal}px)`,
            textShadow: `0 0 35px ${accentColor}44`,
            transition: "none",
          }}
        >
          {secondaryTitle}
        </h2>

        {/* DETECTED BADGE */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            marginTop: height * 0.05,
            opacity: badgeSpring * pulseBlink,
            transform: `translateY(${(1 - badgeSpring) * 15}px)`,
            transition: "none",
          }}
        >
          <div
            style={{
              width: Math.min(width, height) * 0.065,
              height: Math.min(width, height) * 0.065,
              borderRadius: "50%",
              border: `2px solid ${accentColor}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              marginRight: 16,
              boxShadow: `0 0 15px ${accentColor}33`,
              backgroundColor: `${accentColor}15`,
              transition: "none",
            }}
          >
            <svg
              width="45%"
              height="45%"
              viewBox="0 0 24 24"
              fill="none"
              stroke={accentColor}
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <line x1="12" y1="19" x2="12" y2="5" />
              <polyline points="5 12 12 5 19 12" />
            </svg>
          </div>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              fontFamily: interFamily,
              transition: "none",
            }}
          >
            <span
              style={{
                color: accentColor,
                fontWeight: 900,
                fontSize: height * 0.018,
                letterSpacing: "0.15em",
                lineHeight: 1.2,
                transition: "none",
              }}
            >
              STRESS
            </span>
            <span
              style={{
                color: primaryColor,
                fontWeight: 700,
                fontSize: height * 0.015,
                letterSpacing: "0.15em",
                opacity: 0.8,
                lineHeight: 1.2,
                transition: "none",
              }}
            >
              DETECTED
            </span>
          </div>
        </div>
      </div>

      {/* RIGHT COLUMN: CIRCULAR DIAL */}
      <div
        style={{
          position: "absolute",
          top: height * 0.12,
          right: width * 0.08,
          width: width * 0.35,
          height: height * 0.52,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: title2Spring,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "relative",
            width: dialSvgSize,
            height: dialSvgSize,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            transition: "none",
          }}
        >
          {/* Dial Graphic */}
          <svg
            width={dialSvgSize}
            height={dialSvgSize}
            style={{
              position: "absolute",
              transform: "rotate(-120deg)",
              filter: `drop-shadow(0px 0px 15px ${accentColor}15)`,
              transition: "none",
            }}
          >
            <circle
              cx={dialCenter}
              cy={dialCenter}
              r={dialRadius}
              stroke="#0e0e1a"
              strokeWidth="9"
              fill="transparent"
            />
            <circle
              cx={dialCenter}
              cy={dialCenter}
              r={dialRadius}
              stroke={accentColor}
              strokeWidth="9"
              fill="transparent"
              strokeDasharray={dialCircumference}
              strokeDashoffset={strokeDashoffset}
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          </svg>

          {/* Centered Meta Content */}
          <div
            style={{
              position: "absolute",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: interFamily,
              textAlign: "center",
              padding: "20px",
              transition: "none",
            }}
          >
            <span
              style={{
                fontSize: height * 0.015,
                color: "#7e7e9a",
                letterSpacing: "0.22em",
                fontWeight: 600,
                textTransform: "uppercase",
                marginBottom: 10,
                transition: "none",
              }}
            >
              CORTISOL LEVEL
            </span>
            <span
              style={{
                fontFamily: oswaldFamily,
                fontSize: height * 0.11,
                color: accentColor,
                fontWeight: 700,
                lineHeight: 1,
                textShadow: `0 0 35px ${accentColor}40`,
                transition: "none",
              }}
            >
              {Math.floor(countProgress)}%
            </span>
            <span
              style={{
                fontSize: height * 0.015,
                color: accentColor,
                letterSpacing: "0.18em",
                fontWeight: 700,
                textTransform: "uppercase",
                marginTop: 10,
                opacity: interpolate(frame, [spikeStartFrame, spikeEndFrame], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                }),
                transition: "none",
              }}
            >
              ABOVE BASELINE
            </span>
          </div>
        </div>
      </div>

      {/* BOTTOM SECTION: TELEMETRY LINE CHART */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.05,
          left: width * 0.08,
          width: width * 0.84,
          height: height * 0.38,
          transition: "none",
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox="0 0 1000 300"
          style={{ overflow: "visible", transition: "none" }}
        >
          {/* Custom chart definitions for gradients */}
          <defs>
            <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={accentColor} stopOpacity="0.32" />
              <stop offset="100%" stopColor={accentColor} stopOpacity="0.0" />
            </linearGradient>
            <linearGradient id="strokeGradient" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%" stopColor="#2563eb" />
              <stop offset="45%" stopColor="#7c3aed" />
              <stop offset="100%" stopColor={accentColor} />
            </linearGradient>
          </defs>

          {/* Staggered Vertical Grid Telemetry Lines */}
          {verticalGridLines.map((xVal, index) => {
            const lineOpacity = interpolate(
              frame,
              [15 + index * 6, 45 + index * 6],
              [0, 0.12],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            return (
              <line
                key={xVal}
                x1={xVal}
                y1="30"
                x2={xVal}
                y2="270"
                stroke={primaryColor}
                strokeOpacity={lineOpacity}
                strokeDasharray="4 4"
                strokeWidth="1.5"
                style={{ transition: "none" }}
              />
            );
          })}

          {/* Time Marker Labels */}
          {verticalGridLines.map((xVal, index) => {
            const labelOpacity = interpolate(
              frame,
              [35 + index * 5, 65 + index * 5],
              [0, 0.45],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );
            return (
              <text
                key={`lbl-${xVal}`}
                x={xVal}
                y="292"
                fill={primaryColor}
                fillOpacity={labelOpacity}
                fontSize="11"
                fontFamily={interFamily}
                textAnchor="middle"
                style={{ letterSpacing: "0.1em", transition: "none" }}
              >
                T+{(index * 2.5).toFixed(1)}s
              </text>
            );
          })}

          {/* Static horizontal reference baseline */}
          <line
            x1="50"
            y1="270"
            x2="950"
            y2="270"
            stroke="#1a1a2e"
            strokeWidth="1.5"
            style={{ transition: "none" }}
          />

          {/* Dynamic Fill Path Underneath the Line */}
          {hasPoints && (
            <path
              d={fillPath}
              fill="url(#chartGradient)"
              style={{ transition: "none" }}
            />
          )}

          {/* Dynamic Core Biological Line Chart Path */}
          {hasPoints && (
            <path
              d={linePath}
              fill="none"
              stroke="url(#strokeGradient)"
              strokeWidth="3.5"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          )}

          {/* Pulse Target Highlight Node (The Spike Target Point) */}
          {leadPoint && (
            <g style={{ transition: "none" }}>
              <circle
                cx={leadPoint.x}
                cy={leadPoint.y}
                r={10 * pulseScale}
                fill="transparent"
                stroke={accentColor}
                strokeWidth="1.5"
                opacity={pulseOpacity}
                style={{ transition: "none" }}
              />
              <circle
                cx={leadPoint.x}
                cy={leadPoint.y}
                r="13"
                fill={accentColor}
                opacity="0.25"
                style={{ filter: "blur(3px)", transition: "none" }}
              />
              <circle
                cx={leadPoint.x}
                cy={leadPoint.y}
                r="5"
                fill="#ffffff"
                stroke={accentColor}
                strokeWidth="3.5"
                style={{ transition: "none" }}
              />
            </g>
          )}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default CortisolSpike;